import os
import zipfile
import logging
import traceback
from taf.internal.managedobject import ManagedObject
from taf.internal.rpc.pyro.exception import (RequiredSoftwareMissing, PyroServerStartFailure,
                                             SpecifiedFolderNotExisting, UnexpectedSetupServerFailure)
from taf.internal.rpc.pyro.proxy import PyroProxy
from .pyro_server import PyroServerRunner
from .util import upload_file
from .workspace import Workspace
from .environment import RemoteEnvironment


class PyroRPC(ManagedObject):

    def __init__(self, **kwargs):
        super(PyroRPC, self).__init__(**kwargs)
        self._pyro_port = None
        self._env = None
        self._workspace = None
        self._server = None
        self._python_path = 'python'

    @property
    def python_path(self):
        return self._python_path

    @property
    def server_log_path(self):
        return self._server.server_log_path if self._server else None

    @property
    def server_workspace_path(self):
        return self._workspace.workspace_dir

    @property
    def hostname(self):
        return self._env.hostname

    @property
    def port(self):
        return self._pyro_port

    @property
    def workspace(self):
        return self._workspace

    def configure(self, hostname, pyro_port, username=None, password=None, server_dir=None, python_path=None, **kwargs):
        self._pyro_port = pyro_port
        self._python_path = python_path or self._python_path
        self._python_path = self._python_path.replace("\\", "/")
        self._env = self._create_remote_environment(python_path=self._python_path,
                                                    hostname=hostname,
                                                    username=username,
                                                    password=password,
                                                    **kwargs)

        self._workspace = self._create_workspace(base_dir=server_dir,
                                                 workspace_name=self._get_workspace_name(),
                                                 environment=self._env,
                                                 **kwargs)

        self.add_prerequisite(self._workspace)
        self._server = self._create_server_instance()

    def get_remote_log_collectors(self):
        return [self._server, ]

    def _get_workspace_name(self):
        return 'workspace'

    def _create_remote_environment(self, python_path, hostname=hostname, username=None, password=None, **kwargs):
        """
        can be override for creating derived class of RemoteEnvironment class
        """
        return RemoteEnvironment(python_path=python_path,
                                 hostname=hostname,
                                 username=username,
                                 password=password)

    def _create_workspace(self, base_dir, workspace_name, environment, **kwargs):
        """
        can be override for creating derived class of Workspace class
        """
        return Workspace(base_dir=base_dir,
                         workspace_name=workspace_name,
                         environment=environment)

    def _create_server_instance(self):
        """
        assume subclass should override it to return specific server instance
        :return:
        """
        feature_packages = self._get_feature_packages()
        return PyroServerRunner(self._env.hostname, self._pyro_port, self._workspace.workspace_dir,
                                self._env.username, self._env.password, self._python_path,
                                packages=feature_packages, log_dir=self.workspace.log_dir)

    def _setup(self):
        try:
            self._check_environment_prerequisites(self._env)
            self._deploy_server()
            self._start_server()
        except (RequiredSoftwareMissing, PyroServerStartFailure):
            raise
        except Exception as e:
            logging.error('exception is {}, traceback is {}'.format(e, traceback.format_exc()))
            raise UnexpectedSetupServerFailure(e)

    def _check_environment_prerequisites(self, env):
        self._check_required_software(env)
        self._check_required_packages(env)

    def _deploy_server(self):
        self._workspace.create()
        self._transfer_pyro_start_file_to_remote()
        self._transfer_pyro_feature_package_file_to_remote()
        self._transfer_feature_packages_to_remote(self._get_feature_packages())

    def _get_required_software(self):
        return [self._python_path, ]

    def _get_required_packages(self):
        return [('Pyro4', ''), ]

    def _check_required_software(self, env):
        required_softwares = self._get_required_software()
        env.check_required_software(required_softwares)

    def _check_required_packages(self, env):
        required_packages = self._get_required_packages()
        env.check_required_packages(required_packages)

    def _teardown(self):
        self._server.teardown()

    def get_feature_packages(self):
        return self._get_feature_packages()

    def _get_feature_packages(self):
        """
        assume subclass should change the return value as FeaturePackage instances which representing packge code
        will be transferred to remote
        :return:
        """
        return []

    def _start_server(self):
        self._server.setup()

    def _stop_server(self):
        pass

    def _transfer_file_to_remote(self, local_file_path, remote_filename=None):
        if not remote_filename:
            remote_filename = os.path.split(local_file_path)[-1]

        # self._server_dir is separated by '/' and end with '/'
        remote_path = self._workspace.workspace_dir + remote_filename
        upload_file(local_file_path,
                    remote_path,
                    self._env.connection)

    def _transfer_pyro_start_file_to_remote(self):
        start_file_relative_path = 'server/start.py'
        local_start_file_path = \
            os.path.join(os.path.dirname(__file__), start_file_relative_path).replace('\\', '/')
        self._transfer_file_to_remote(local_start_file_path)

    def _transfer_pyro_feature_package_file_to_remote(self):
        start_file_relative_path = 'server/feature_package.py'
        local_start_file_path = \
            os.path.join(os.path.dirname(__file__), start_file_relative_path).replace('\\', '/')
        self._transfer_file_to_remote(local_start_file_path)

    def _transfer_feature_packages_to_remote(self, packages):
        for package in packages:
            if not os.path.exists(package.server_code_full_local_path):
                raise SpecifiedFolderNotExisting("path {}".format(str(package.server_code_full_local_path)))

            if os.path.isdir(package.server_code_full_local_path):
                zipfile_path = package.server_code_full_local_path + ".zip"
                self._zip_dir(package.server_code_full_local_path, zipfile_path)
                self._transfer_file_to_remote(zipfile_path, package.remote.server_package_name + ".zip")
                os.remove(zipfile_path)

    def create_proxy(self, hostname=None, port=None, timeout=600, **kwargs):
        """
        create proxy for the server belonging to the same rpc, or a server indicated by hostname and port
        should be override by derived class
        """
        if not hostname and not port:
            return PyroProxy(self._server.uri, timeout=timeout)
        server_uri = PyroServerRunner.create_server_uri(hostname, port)
        return PyroProxy(server_uri, timeout=timeout)

    def run_shell_command(self, command, proxy=None):
        return proxy.run_shell_command(command)

    def _zip_dir(self, dir_path, out_file_name):
        zip_file = zipfile.ZipFile(out_file_name, "w", zipfile.ZIP_DEFLATED)
        for path, _, filenames in os.walk(dir_path):
            fpath = path.replace(dir_path, '')
            for filename in filenames:
                zip_file.write(os.path.join(path, filename), os.path.join(fpath, filename))
        zip_file.close()
